///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.searchFaq
 * @author Inswave
 * @date 2026. 09. 29
 * @param _helpClssId
 * @returns
 * @hidden N
*/
scwin.searchFaq = async function (_helpClssId) {
    /* sdd-asis-lifecycle:begin fn_SearchFaq — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.faqForm || { elements: [] });
    $c.util.getComponent('dma_SearchFaqReq').set('helpClssId', _helpClssId);
    $c.util.getComponent("ipt_keyword").setValue('');
    frm.action = 'faq.do';
    $c.util.getComponent('dma_SearchFaqReq').set('method', 'searchFAQ');
    await scwin.tx_fn_SearchFaq();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.faqForm || { elements: [] });
    $c.util.getComponent('dma_SearchFaqReq').set('helpClssId', $c.util.getComponent('slc_helpClssIdSel').getValue());
    frm.action = 'faq.do';
    $c.util.getComponent('dma_SearchFaqReq').set('method', 'searchFAQ');
    await scwin.tx_fn_Search();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.print
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.print = function () {
    /* sdd-asis-lifecycle:begin fn_Print — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.popupPrint();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.viewAnswer
 * @author Inswave
 * @date 2026. 09. 29
 * @param _faqId
 * @returns
 * @hidden N
*/
scwin.viewAnswer = function (_faqId) {
    /* sdd-asis-lifecycle:begin fn_ViewAnswer — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const divObj = $c.util.getComponent('answer_' + _faqId);
    const dispalyVal = divObj.style.display;
    if (dispalyVal === 'none') {
        divObj.style.display = 'inline';
    } else {
        if (dispalyVal === 'inline') {
            divObj.style.display = 'none';
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.initValue
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.initValue = function () {
    /* sdd-asis-lifecycle:begin fn_InitValue — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.faqForm || { elements: [] });
    $c.util.getComponent("slc_helpClssIdSel").setValue("" + dma_pageContext.get("helpClssIdSel") + "");
    /* sdd-asis-lifecycle:end */
};
